"""Compare the built CLI with fixtures generated by the pinned Go source."""

import base64
import json
from pathlib import Path
import subprocess
import sys


def invoke(binary, arguments):
    result = subprocess.run(
        [str(binary), *arguments], capture_output=True, text=True, timeout=15
    )
    if result.returncode != 0:
        raise AssertionError(
            f"{arguments[0]} exited {result.returncode}: {result.stderr.strip()}"
        )
    return result.stdout.rstrip("\n")


def standard(value):
    raw = base64.urlsafe_b64decode(value + "=" * (-len(value) % 4))
    return base64.b64encode(raw).decode("ascii")


def check(binary, fixture_path):
    vectors = json.loads(fixture_path.read_text())
    assert vectors["reference"] == (
        "Xray-core 67756b3674d56b72c7a7e675e8dcd3f883e1b2f7"
    )
    assert len(vectors["mlkem768"]) >= 5
    assert len(vectors["x25519"]) >= 5
    comparisons = 0
    for vector in vectors["mlkem768"]:
        expected = (
            f"Seed: {vector['seed']}\n"
            f"Client: {vector['client']}\n"
            f"Hash32: {vector['hash32']}"
        )
        actual = invoke(binary, ["mlkem768", "-i", vector["seed"]])
        assert actual == expected, f"ML-KEM Go mismatch: {vector['name']}"
        comparisons += 1
    for vector in vectors["x25519"]:
        for standard_encoding in (False, True):
            encode = standard if standard_encoding else lambda value: value
            arguments = ["x25519", "-i", encode(vector["input"])]
            if standard_encoding:
                arguments.append("--std-encoding")
            expected = (
                f"PrivateKey: {encode(vector['private_key'])}\n"
                f"Password (PublicKey): {encode(vector['public_key'])}\n"
                f"Hash32: {encode(vector['hash32'])}"
            )
            actual = invoke(binary, arguments)
            assert actual == expected, f"X25519 Go mismatch: {vector['name']}"
            comparisons += 1
    print(f"Built CLI matches pinned Go output in {comparisons} comparisons")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit("Usage: check-key-cli-parity.py XRAY_BINARY GO_VECTORS_JSON")
    check(Path(sys.argv[1]).resolve(), Path(sys.argv[2]))
